package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetMemberUseCase;
import com.example.lending.application.port.in.ListMemberLoansUseCase;
import com.example.lending.application.port.in.RegisterMemberUseCase;
import com.example.lending.application.port.in.RegisterMemberUseCase.RegisterMemberCommand;
import com.example.lending.domain.Member;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.UUID;

@RestController
@RequestMapping("/members")
public class MemberController {

    private final RegisterMemberUseCase registerMemberUseCase;
    private final GetMemberUseCase getMemberUseCase;
    private final ListMemberLoansUseCase listMemberLoansUseCase;

    public MemberController(RegisterMemberUseCase registerMemberUseCase, GetMemberUseCase getMemberUseCase,
                            ListMemberLoansUseCase listMemberLoansUseCase) {
        this.registerMemberUseCase = registerMemberUseCase;
        this.getMemberUseCase = getMemberUseCase;
        this.listMemberLoansUseCase = listMemberLoansUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public MemberResponse registerMember(@RequestBody RegisterMemberRequest request) {
        Member member = registerMemberUseCase.registerMember(new RegisterMemberCommand(request.memberId(), request.name()));
        return MemberResponse.from(member);
    }

    @GetMapping("/{memberId}")
    public MemberResponse getMember(@PathVariable UUID memberId) {
        return MemberResponse.from(getMemberUseCase.getMember(memberId));
    }

    // 반납하지 않은 대출만 조회한다. page 는 0부터 시작하며 totalCount 는 페이지와 무관한 전체 건수다.
    @GetMapping("/{memberId}/loans")
    public MemberLoansResponse listActiveLoans(@PathVariable UUID memberId,
                                               @RequestParam(defaultValue = "0") int page,
                                               @RequestParam(defaultValue = "20") int size) {
        return MemberLoansResponse.from(listMemberLoansUseCase.listActiveLoans(memberId, page, size));
    }
}
