package com.example.lending.application.service;

import com.example.lending.application.port.in.ListMemberLoansUseCase;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
@Transactional(readOnly = true)
public class ListMemberLoansService implements ListMemberLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanPort loadLoanPort;

    public ListMemberLoansService(LoadMemberPort loadMemberPort, LoadLoanPort loadLoanPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanPort = loadLoanPort;
    }

    @Override
    public ActiveLoanPage listActiveLoans(UUID memberId, int page, int size) {
        if (page < 0) {
            throw new IllegalArgumentException("page must not be negative");
        }
        if (size < 1) {
            throw new IllegalArgumentException("size must be at least 1");
        }
        loadMemberPort.loadMember(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
        return loadLoanPort.loadActiveLoans(memberId, page, size);
    }
}
