package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

import java.util.ArrayList;

class LoanMapper {

    Loan toDomain(LoanJpaEntity entity) {
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(),
                entity.getLoanedAt(), entity.getDueAt(), entity.getReturnedAt(), toCreditCheck(entity.getCreditCheck()));
    }

    LoanJpaEntity toEntity(Loan loan) {
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(),
                loan.getLoanedAt(), loan.getDueAt(), loan.getReturnedAt(), toEmbeddable(loan.getCreditCheck()));
    }

    private CreditCheck toCreditCheck(CreditCheckEmbeddable embeddable) {
        if (embeddable == null) {
            return null;
        }
        return new CreditCheck(embeddable.getCreditApproved(), embeddable.getCreditScore(),
                embeddable.getCreditReasonCodes(), embeddable.getCreditCheckedAt(),
                embeddable.getCreditProviderName(), embeddable.getCreditProviderVersion());
    }

    private CreditCheckEmbeddable toEmbeddable(CreditCheck creditCheck) {
        if (creditCheck == null) {
            return null;
        }
        return new CreditCheckEmbeddable(creditCheck.approved(), creditCheck.score(), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion(), new ArrayList<>(creditCheck.reasonCodes()));
    }
}

