package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoanHistoryApiTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void member_without_loans_gets_an_empty_list() throws Exception {
        String memberId = registerMember("서하린");

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void returned_and_active_loans_are_all_included_newest_loan_first() throws Exception {
        String memberId = registerMember("윤도현");
        String oldLoanId = loanBook(registerBook("Clean Code"), memberId, "2026-03-02");
        String newLoanId = loanBook(registerBook("Refactoring"), memberId, "2026-03-10");
        returnLoan(oldLoanId, "2026-03-21");

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].loanId").value(newLoanId))
                .andExpect(jsonPath("$[0].title").value("Refactoring"))
                .andExpect(jsonPath("$[0].loanedAt").value("2026-03-10"))
                .andExpect(jsonPath("$[0].returnedAt").doesNotExist())
                .andExpect(jsonPath("$[0].lateFee").doesNotExist())
                .andExpect(jsonPath("$[1].loanId").value(oldLoanId))
                .andExpect(jsonPath("$[1].title").value("Clean Code"))
                .andExpect(jsonPath("$[1].loanedAt").value("2026-03-02"))
                .andExpect(jsonPath("$[1].returnedAt").value("2026-03-21"))
                .andExpect(jsonPath("$[1].lateFee").value(500));
    }

    @Test
    void returned_loan_on_time_has_zero_late_fee() throws Exception {
        String memberId = registerMember("배수아");
        String loanId = loanBook(registerBook("Effective Java"), memberId, "2026-01-01");
        returnLoan(loanId, "2026-01-15");

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].returnedAt").value("2026-01-15"))
                .andExpect(jsonPath("$[0].lateFee").value(0));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans/history", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    String loanBook(String bookId, String memberId, String loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId
                                + "\",\"loanedAt\":\"" + loanedAt + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode body = objectMapper.readTree(loaned);
        assertThat(body.get("loanId")).isNotNull();
        return body.get("loanId").asText();
    }

    void returnLoan(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }
}

